<body>
@php
$w=$workspace??[];
$c=$customer??null;
$sr=collect($serviceRequests??[]);
$wo=collect($workOrders??[]);
$ct=collect($contracts??[]);
$inv=collect($invoices??[]);
$qt=collect($quotations??[]);
$as=collect($assets??[]);
$si=collect($sites??[]);
$vi=collect($visits??[]);
$isAr=app()->getLocale()==='ar';
$name=data_get($c,'name',data_get($w,'customer.name','Customer'));
$id=data_get($c,'id',data_get($w,'customer.id','—'));
$code=data_get($c,'customer_code',data_get($w,'customer.code','—'));
$email=data_get($c,'email',data_get($c,'main_email',data_get($w,'customer.email','—')));
$phone=data_get($c,'phone',data_get($c,'mobile',data_get($w,'customer.phone','—')));
$city=data_get($c,'city',data_get($w,'customer.city','—'));
$contact=data_get($c,'contact_person',data_get($c,'contact_name',data_get($w,'customer.contact','—')));
$status=strtoupper((string)data_get($c,'status',data_get($w,'customer.status','ACTIVE')));
$created=(string)data_get($c,'created_at','');
$customerSince=data_get($w,'customer.since',$created!==''?substr($created,0,4):'—');
$openSr=data_get($w,'metrics.open_requests',$sr->whereNotIn('status',['COMPLETED','CLOSED','CANCELLED'])->count());
$openWo=data_get($w,'metrics.open_work_orders',$wo->whereNotIn('status',['COMPLETED','CLOSED','CANCELLED'])->count());
$assetsN=data_get($w,'metrics.assets',$as->count());
$sitesN=data_get($w,'metrics.sites',$si->count());
$pendingQ=data_get($w,'metrics.pending_quotations',$qt->whereNotIn('status',['APPROVED','REJECTED','CANCELLED'])->count());
$balance=(float)data_get($w,'metrics.open_balance',$inv->whereNotIn('status',['PAID','CANCELLED'])->sum('total_amount'));
$activeCt=$ct->where('status','ACTIVE')->count();
$sla=data_get($w,'metrics.sla_compliance','N/A');
$overdueWo=$wo->filter(function($x){$s=strtoupper((string)data_get($x,'status',''));if($s==='OVERDUE')return true;$due=data_get($x,'due_date');return $due && strtotime((string)$due)<time() && !in_array($s,['COMPLETED','CLOSED','CANCELLED']);})->count();
$upcomingVisits=$vi->filter(function($x){$d=data_get($x,'scheduled_at',data_get($x,'visit_date'));return !$d || strtotime((string)$d)>=strtotime('today');})->count();
$serviceStatuses=['NEW'=>['New','جديد','#2b7de9'],'UNDER_REVIEW'=>['Under review','تحت المراجعة','#1682df'],'ASSIGNED'=>['Assigned','تم الإسناد','#805ad5'],'IN_PROGRESS'=>['In progress','قيد التنفيذ','#e75a6a'],'TEAM_DISPATCHED'=>['Team dispatched','تم إرسال الفريق','#ff7f66'],'AWAITING_CUSTOMER'=>['Waiting customer','بانتظار العميل','#e59b24'],'COMPLETED'=>['Completed','مكتمل','#16a36a']];
$workStatuses=['NEW'=>['New','جديد','#2b7de9'],'PLANNING'=>['Planning','تخطيط','#5aa9ef'],'ASSIGNED'=>['Assigned','تم الإسناد','#805ad5'],'IN_PROGRESS'=>['In progress','قيد التنفيذ','#e75a6a'],'OVERDUE'=>['Overdue','متأخر','#df0b27'],'ON_HOLD'=>['On hold','معلق','#e59b24'],'COMPLETED'=>['Completed','مكتمل','#16a36a']];
$srTotal=max(1,$sr->count());$woTotal=max(1,$wo->count());
$srLead=$sr->where('status','UNDER_REVIEW')->count();$srPct=(int)round(($srLead/$srTotal)*100);
$woPct=(int)round(($overdueWo/$woTotal)*100);
$operational=$as->filter(fn($x)=>in_array(strtoupper((string)data_get($x,'status','ACTIVE')),['ACTIVE','OPERATIONAL','AVAILABLE']))->count();
$assetPct=$assetsN>0?(int)round(($operational/$assetsN)*100):0;
$underMaintenance=$as->filter(fn($x)=>in_array(strtoupper((string)data_get($x,'status','')),['UNDER_MAINTENANCE','MAINTENANCE']))->count();
$stopped=$as->filter(fn($x)=>in_array(strtoupper((string)data_get($x,'status','')),['STOPPED','OUT_OF_SERVICE','INACTIVE']))->count();
$critical=$as->filter(fn($x)=>strtoupper((string)data_get($x,'condition',data_get($x,'health_status','')))==='CRITICAL')->count();
$months=[];$maxMonthly=1;
for($i=5;$i>=0;$i--){$d=now()->copy()->subMonths($i);$key=$d->format('Y-m');$srM=$sr->filter(fn($x)=>substr((string)data_get($x,'created_at',''),0,7)===$key)->count();$woM=$wo->filter(fn($x)=>substr((string)data_get($x,'created_at',''),0,7)===$key)->count();$maxMonthly=max($maxMonthly,$srM,$woM);$months[]=['label'=>$d->format('M'),'sr'=>$srM,'wo'=>$woM];}
$actionCount=max($pendingQ,$overdueWo);
@endphp
